import React, { useState } from 'react';
import './Wallet.css';

function Wallet() {
  const [balance] = useState(500000);
  const [transactions] = useState([
    { id: 1, type: 'Nạp Tiền', amount: 500000, date: '10/01/2025', status: 'Thành công' },
    { id: 2, type: 'Mua Acc', amount: -200000, date: '09/01/2025', status: 'Thành công' },
    { id: 3, type: 'Bonus', amount: 50000, date: '08/01/2025', status: 'Thành công' }
  ]);

  return (
    <div className="wallet-container">
      <h1>💰 TÀI KHOẢN TIỀN</h1>

      <div className="wallet-content">
        <div className="balance-card">
          <h2>Số Dư Hiện Tại</h2>
          <div className="balance-amount">
            {balance.toLocaleString('vi-VN')} <span>đ</span>
          </div>
          <button className="btn-recharge">+ NẠP TIỀN</button>
        </div>

        <div className="transactions-section">
          <h2>📝 Lịch Sử Giao Dịch</h2>
          <div className="transactions-list">
            {transactions.map(tx => (
              <div key={tx.id} className="transaction-item">
                <div className="tx-info">
                  <div className="tx-type">{tx.type}</div>
                  <div className="tx-date">{tx.date}</div>
                </div>
                <div className={`tx-amount ${tx.amount > 0 ? 'income' : 'expense'}`}>
                  {tx.amount > 0 ? '+' : ''}{tx.amount.toLocaleString('vi-VN')} đ
                </div>
                <div className="tx-status">{tx.status}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Wallet;
